mapper.select:
SELECT COUNT(DISTINCT gs.user_id)
FROM game_score gs
WHERE gs.game_code = #{gameCode}
  AND gs.valid = 1
  AND gs.played_at >= #{start}
  AND gs.played_at < #{end}

SELECT

        MIN(gs.score)
        MAX(gs.score)

FROM game_score gs
WHERE gs.game_code = #{gameCode}
  AND gs.user_id = #{userId}
  AND gs.valid = 1
  AND gs.played_at >= #{start}
  AND gs.played_at < #{end}
